package com.example.salarygrows;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.text.InputType;import android.text.TextWatcher;import android.text.Editable;import java.time.*;import java.text.*;import java.util.*;
public class MainActivity extends Activity {
 SharedPreferences prefs; EditText salary,netSalary,payday; Spinner displayMode; Switch transparentMode; TextView preview,previewPercent; Spinner workType; EditText weeklyHours; Switch pensionOn,healthOn,employmentOn; TextView insuranceResult; Handler handler=new Handler(); Runnable ticker;
 int dp(int v){return (int)(v*getResources().getDisplayMetrics().density);} TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(size);return t;}
 void add(LinearLayout l,View v){LinearLayout.LayoutParams a=new LinearLayout.LayoutParams(-1,-2);a.bottomMargin=dp(14);l.addView(v,a);} EditText field(long n){EditText e=new EditText(this);e.setText(String.valueOf(n));e.setTextColor(Color.WHITE);e.setInputType(InputType.TYPE_CLASS_NUMBER);e.setSingleLine(true);return e;}
 long number(EditText e){return Long.parseLong(e.getText().toString().replace(",", "").trim());}
 void commas(EditText e){e.setText(NumberFormat.getIntegerInstance(Locale.KOREA).format(number(e)));e.setSelection(e.length());e.addTextChangedListener(new TextWatcher(){boolean busy=false;public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){if(busy)return;String digits=s.toString().replaceAll("[^0-9]", "");if(digits.isEmpty())return;try{String formatted=NumberFormat.getIntegerInstance(Locale.KOREA).format(Long.parseLong(digits));if(!formatted.equals(s.toString())){busy=true;e.setText(formatted);e.setSelection(e.length());busy=false;}}catch(Exception ex){busy=false;}}public void afterTextChanged(Editable x){}});}

 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("salary",MODE_PRIVATE);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(0xff101827);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(24),dp(35),dp(24),dp(24));scroll.addView(l);setContentView(scroll);
 add(l,text("월급이 자란다 💵",28));add(l,text("매월 1일~말일 · 24시간 균등 적립",14));preview=text("",28);preview.setTextColor(0xffFF5B5B);preview.setTypeface(null,1);preview.setSingleLine(true);preview.setAutoSizeTextTypeUniformWithConfiguration(18,28,1,1);add(l,preview);previewPercent=text("",28);previewPercent.setTextColor(0xffFF5B5B);previewPercent.setTypeface(null,1);previewPercent.setSingleLine(true);previewPercent.setAutoSizeTextTypeUniformWithConfiguration(18,28,1,1);add(l,previewPercent);
 add(l,text("월급 (원)",16));salary=field(prefs.getLong("salary_amount",prefs.getLong("net",2500000)));commas(salary);add(l,salary);
 add(l,text("세후 월급 (원)",16));netSalary=field(prefs.getLong("net_salary_amount",prefs.getLong("net",2200000)));commas(netSalary);add(l,netSalary);
 add(l,text("위젯 월급 표시 방식",16));displayMode=new Spinner(this);String[] displayOptions={"구분 없이 월급만 표시", "세전 월급 표시", "세후 월급 표시"};ArrayAdapter<String> displayAdapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,displayOptions);displayMode.setAdapter(displayAdapter);displayMode.setSelection(Math.max(0,Math.min(2,prefs.getInt("display_mode",0))));add(l,displayMode);
 add(l,text("월급날 (1~31)",16));payday=field(prefs.getInt("payday",10));add(l,payday);

 transparentMode=new Switch(this);transparentMode.setText("위젯 투명 배경 (끄면 기존 남색)");transparentMode.setTextColor(Color.WHITE);transparentMode.setChecked(prefs.getBoolean("transparent_bg",false));add(l,transparentMode);
 add(l,text("4대보험 예상 계산 (참고용)",21));
 add(l,text("근로 형태",16));workType=new Spinner(this);String[] types={"정규직","계약직","단시간 근로자"};ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,types);workType.setAdapter(adapter);workType.setSelection(prefs.getInt("work_type",0));add(l,workType);
 add(l,text("주당 근로시간",16));weeklyHours=field(prefs.getInt("weekly_hours",40));add(l,weeklyHours);
 add(l,text("가입 여부는 근로시간 외에도 나이·계약기간·사업장 조건 등에 따라 달라질 수 있습니다. 실제 가입 내역에 맞게 아래 항목을 조정하세요.",13));
 pensionOn=new Switch(this);pensionOn.setText("국민연금 적용");pensionOn.setTextColor(Color.WHITE);pensionOn.setChecked(prefs.getBoolean("insurance_pension",true));add(l,pensionOn);
 healthOn=new Switch(this);healthOn.setText("건강보험·장기요양 적용");healthOn.setTextColor(Color.WHITE);healthOn.setChecked(prefs.getBoolean("insurance_health",true));add(l,healthOn);
 employmentOn=new Switch(this);employmentOn.setText("고용보험 적용");employmentOn.setTextColor(Color.WHITE);employmentOn.setChecked(prefs.getBoolean("insurance_employment",true));add(l,employmentOn);
 Button calculate=new Button(this);calculate.setText("4대보험 예상액 계산");add(l,calculate);insuranceResult=text("",15);add(l,insuranceResult);
 calculate.setOnClickListener(v->{try{long g=number(salary);if(g<0)throw new Exception();int hours=Integer.parseInt(weeklyHours.getText().toString());if(hours<0||hours>168)throw new Exception();long[] a=InsuranceEstimate.calculate(g,pensionOn.isChecked(),healthOn.isChecked(),employmentOn.isChecked());long total=a[0]+a[1]+a[2]+a[3];insuranceResult.setText("국민연금: "+SalaryCalc.won(a[0])+"\n건강보험: "+SalaryCalc.won(a[1])+"\n장기요양보험: "+SalaryCalc.won(a[2])+"\n고용보험: "+SalaryCalc.won(a[3])+"\n산재보험: 근로자 부담 0원\n보험료 합계: "+SalaryCalc.won(total)+"\n보험료 공제 후: "+SalaryCalc.won(g-total)+"\n\n※ 소득세·지방소득세는 포함하지 않은 예상액입니다. 실제 실수령액과 다릅니다. 보험료는 기준소득월액·보수월액·상한액 및 개인별 자격에 따라 달라집니다. 단시간 근로자는 가입 예외가 있을 수 있습니다. 위젯에는 입력한 월급이 표시됩니다.");}catch(Exception e){Toast.makeText(this,"월급과 근로시간을 확인해",Toast.LENGTH_LONG).show();}});
 Button save=new Button(this);save.setText("설정 저장 / 위젯 갱신");add(l,save);add(l,text("홈 화면 길게 누르기 → 위젯 → 월급이 자란다. 위젯을 누르면 설정 화면이 열려.",13));
 save.setOnClickListener(v->{try{long g=number(salary);long netValue=number(netSalary);if(netValue<0)throw new Exception();int d=Integer.parseInt(payday.getText().toString());if(g<0||d<1||d>31)throw new Exception();int hours=Integer.parseInt(weeklyHours.getText().toString());if(hours<0||hours>168)throw new Exception();prefs.edit().putInt("work_type",workType.getSelectedItemPosition()).putInt("weekly_hours",hours).putBoolean("insurance_pension",pensionOn.isChecked()).putBoolean("insurance_health",healthOn.isChecked()).putBoolean("insurance_employment",employmentOn.isChecked()).putLong("salary_amount",g).putLong("net_salary_amount",netValue).putInt("display_mode",displayMode.getSelectedItemPosition()).putInt("payday",d).putBoolean("transparent_bg",transparentMode.isChecked()).apply();SalaryWidget.refresh(this);Toast.makeText(this,"저장 완료",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"입력값을 확인해",Toast.LENGTH_LONG).show();}});
 ticker=new Runnable(){public void run(){int mode=prefs.getInt("display_mode",0);long target=mode==2?prefs.getLong("net_salary_amount",prefs.getLong("net",2200000)):prefs.getLong("salary_amount",prefs.getLong("net",2500000));LocalDateTime now=LocalDateTime.now();int days=YearMonth.from(now).lengthOfMonth();double f=((now.getDayOfMonth()-1)*86400d+now.getHour()*3600d+now.getMinute()*60d+now.getSecond())/(days*86400d);preview.setText((mode==1?"세전 ":mode==2?"세후 ":"")+NumberFormat.getIntegerInstance(Locale.KOREA).format((long)(target*f))+"원");previewPercent.setText(String.format(Locale.KOREA,"%.2f%% 달성",f*100));handler.postDelayed(this,1000);}};handler.post(ticker);
 }
 @Override protected void onDestroy(){handler.removeCallbacks(ticker);super.onDestroy();}
}